import json
tokens = [5, 19, 2, 23, 40, 2, 5]
def rule(prefix):
    probe = prefix[-1]
    cut = prefix.index(40)
    for i in range(0, cut, 2):
        if prefix[i] == probe:
            return prefix[i + 1]
    return -1
print(json.dumps({"after_2": rule(tokens[:6]), "after_5": rule(tokens[:7])}))
